           when options = '["Automated cutoff optimisation across zones", "Multi-well batch interpretation of the full field", "Triangulating Rw itself from a temperature-corrected lab sample, an SP quicklook and the Pickett fit", "Replacing the Archie family with resistivity-independent saturation methods"]'::jsonb then 'old'
           when options = '["Automated cutoff optimisation across zones", "Multi-well batch interpretation of the full field", "Triangulating Rw itself from a temperature-corrected lab sample, an SP quicklook and the Pickett fit", "Replacing the Archie family with resistivity-independent saturation methods such as capillary-pressure height functions"]'::jsonb then 'new'
           else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'petrophysics' and tier = 'intermediate' and scope = 'module' and module_key is not distinct from 'm06-method-choice-and-reporting' and ord = 15;
  if v_state is null then raise exception 'answer-length recut, petrophysics refused: no row for intermediate module m06-method-choice-and-reporting ord 15'; end if;
  if v_state = 'other' then raise exception 'answer-length recut, petrophysics refused: intermediate module m06-method-choice-and-reporting ord 15 matches neither its published nor its recut form'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set options = '["Automated cutoff optimisation across zones", "Multi-well batch interpretation of the full field", "Triangulating Rw itself from a temperature-corrected lab sample, an SP quicklook and the Pickett fit", "Replacing the Archie family with resistivity-independent saturation methods such as capillary-pressure height functions"]'::jsonb
     where app_slug = 'petrophysics' and tier = 'intermediate' and scope = 'module' and module_key is not distinct from 'm06-method-choice-and-reporting' and ord = 15;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'answer-length recut, petrophysics refused: intermediate module m06-method-choice-and-reporting ord 15 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_total from public.academy_quiz_questions where app_slug = 'petrophysics';
  if v_total <> 394 then raise exception 'answer-length recut, petrophysics refused: the course holds % questions, expected 394', v_total; end if;
  raise notice 'answer-length recut, petrophysics: % of 118 rows updated, the rest already carried the recut text', v_updated;
end $$;
